import{_ as r,l as p,o as e,c as n,v as t,p as i,x as o,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"bump 分配与 TLAB","description":"","frontmatter":{"title":"bump 分配与 TLAB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bump-allocation-tlab.md","filePath":"cs/bump-allocation-tlab.md","lastUpdated":1789023840000}'),m={name:"cs/bump-allocation-tlab.md"};function A(b,a,u,T,h,B){const l=p("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="bump-分配与-tlab" tabindex="-1">bump 分配与 TLAB <a class="header-anchor" href="#bump-分配与-tlab" aria-label="Permalink to &quot;bump 分配与 TLAB&quot;">​</a></h1><div class="epigraph"><p>在连续空闲区上移动指针即可分配：bump pointer。多线程各持 TLAB（线程本地分配缓冲），避免在 Eden 上全局加锁。</p><footer>—— 据 Appel 分代分配；HotSpot TLAB；Jones 手册整理</footer></div><p>上一课<a href="/cs/generational-promotion">分代晋升</a> 的 Eden 需要极快分配。缺口是<strong>实现</strong>：bump 与 TLAB。弱引用下一课。与<a href="/cs/linear-scan-regalloc">线性扫描</a> 无关——那是寄存器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空闲链表 <code>malloc</code> 太慢。复制式/分代 Eden 是空的连续区：<code>top+=size</code>。多线程争 <code>top</code> 则原子瓶颈。TLAB：每线程一块，本地 bump，耗尽再向堆要。缺口是<strong>无锁快路径</strong>，不是年龄表。</p><p>对象头、对齐、数组长度写在 bump 之后。</p><h3 id="tlab-不是寄存器-tlab-的笔误" tabindex="-1">TLAB 不是寄存器 TLAB 的笔误 <a class="header-anchor" href="#tlab-不是寄存器-tlab-的笔误" aria-label="Permalink to &quot;TLAB 不是寄存器 TLAB 的笔误&quot;">​</a></h3><p>Thread-Local Allocation Buffer。不要和 table 混。</p><p><span class="marginnote">Appel。HotSpot TLAB 自适应大小。本课与逃逸：栈分配更省，TLAB 是堆快路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>慢路径：锁或 CAS 切一块 Eden 给 TLAB。快路径：内联 <code>if (top+size&lt;=end)</code>。GC 时废弃或回收 TLAB 剩余。</p>',11)),(e(),i(c,null,{default:o(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22new%22%5D%20--%3E%20TLAB%5B%22%E7%BA%BF%E7%A8%8B%20bump%22%5D%0A%20%20TLAB%20--%3E%20OK%5B%22%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20TLAB%20--%3E%20REFILL%5B%22%E5%90%91%20Eden%20%E5%86%8D%E8%A6%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 JIT：分配序列是热内联点。与写屏障：新对象在 Eden，store 到老对象才脏卡。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浪费：TLAB 末尾空洞。自适应：按线程分配速率调大小。不要在 TLAB 里放必须零填的巨大数组而不考虑预零页。</p><p>并发 GC：分配与标记交错，对象须正确着色（黑分配等）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写弱引用。后课默认：Eden 用 bump+TLAB。下一课弱引用与终结器。</p><p>也不把 bump 当磁盘分配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bump：连续区指针移动分配。</li><li>TLAB：每线程一块，快路径无锁。</li><li>GC 与并发着色要与分配协议对齐。</li><li>出处：Appel；HotSpot TLAB；Jones 手册。</li></ul>',9))])}const f=r(m,[["render",A]]);export{L as __pageData,f as default};
